// Belle limita 3 meses por requisição
// Gera intervalos de 3 meses desde Jan/2020 até hoje
const intervalos = [];

const fmt = (d) => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;

let inicio = new Date(2020, 0, 1); // 01/01/2020
const hoje = new Date();

while (inicio <= hoje) {
  const fim = new Date(inicio);
  fim.setMonth(fim.getMonth() + 3);
  fim.setDate(fim.getDate() - 1); // último dia do intervalo

  const fimReal = fim > hoje ? hoje : fim;

  intervalos.push({
    json: {
      dtInicio: fmt(inicio),
      dtFim:    fmt(fimReal)
    }
  });

  inicio.setMonth(inicio.getMonth() + 3);
}

console.log(`Total de intervalos: ${intervalos.length}`);
return intervalos;

const vendas = [];

const parseDateBR = (s) => {
  if (!s) return null;
  const p = s.split('/');
  if (p.length === 3) return `${p[2]}-${p[1]}-${p[0]}`;
  return null;
};

const parseValor = (v) => {
  if (!v) return 0;
  return parseFloat(String(v).replace(/\./g, '').replace(',', '.')) || 0;
};

for (const item of $input.all()) {
  const data = item.json;
  const lista = Array.isArray(data) ? data : (data.codOrcamento ? [data] : []);

  for (const v of lista) {
    if (!v.codOrcamento) continue;

    // Extrair codCliente do campo 'cliente': '1 - José da Silva'
    const codClienteMatch = String(v.cliente || '').match(/^(\d+)/);
    const codCliente = codClienteMatch ? parseInt(codClienteMatch[1]) : null;

    // Total de sessões somando qtdSessoes de todos os serviços
    const servicos = v.servicos || [];
    const sessoesTotal = servicos.reduce((acc, s) => {
      return acc + (parseInt(s.qtdSessoes || s.qtdSes || s.sessoes || 0));
    }, 0);

    vendas.push({
      json: {
        belle_id:          v.codOrcamento,
        belle_cliente_cod: codCliente,
        id_venda:          v.idVenda || null,
        nome_protocolo:    (v.nomePlano || v.descricao || '').replace(/'/g, "''"),
        tipo_plano:        v.tipoPlano || '',
        servicos:          JSON.stringify(servicos),
        valor_bruto:       parseValor(v.preco),
        valor_final:       parseValor(v.precoFinal),
        sessoes_total:     sessoesTotal,
        data_venda:        parseDateBR(v.dataVenda),
        vendedor:          (v.vendedor || '').replace(/'/g, "''"),
        status_plano:      v.statusPlano || 'Aprovado'
      }
    });
  }
}

console.log(`Total de vendas encontradas: ${vendas.length}`);
return vendas;

const venda = $('Filtrar e Normalizar Vendas').item.json;
const planosCliente = $input.item.json;

const planos = Array.isArray(planosCliente) ? planosCliente : (planosCliente.codPlano ? [planosCliente] : []);
const planoMatch = planos.find(p => String(p.codPlano) === String(venda.belle_id));

let sessoesRealizadas = 0;

if (planoMatch && planoMatch.servicos) {
  const saldoRestante = planoMatch.servicos.reduce((acc, s) => {
    return acc + (parseInt(s.saldoRestante) || 0);
  }, 0);
  sessoesRealizadas = Math.max(0, (venda.sessoes_total || 0) - saldoRestante);
}

return {
  json: {
    ...venda,
    sessoes_realizadas: sessoesRealizadas
  }
};
